function validate(input) {
  const [nums, fn, init] = input;
  if (!Array.isArray(nums) || nums.length > 1000) return 'nums has at most 1000 elements.';
  if (!nums.every(value => Number.isInteger(value) && value >= 0 && value <= 1000)) return 'Every element of nums is an integer from 0 to 1000.';
  if (!['sum', 'sumOfSquares', 'zero', 'max', 'hash', 'last'].includes(fn)) return 'fn must be "sum", "sumOfSquares", "zero", "max", "hash" or "last".';
  if (!Number.isInteger(init) || init < 0 || init > 1000) return 'init must be an integer from 0 to 1000.';
  return null;
}

