function adapt(input, solve, kit) {
  const [nums, name, init] = input;
  const reducers = {
    sum: (accum, curr) => accum + curr,
    sumOfSquares: (accum, curr) => accum + curr * curr,
    zero: () => 0,
    max: (accum, curr) => Math.max(accum, curr),
    hash: (accum, curr) => (accum * 31 + curr) % 1000000007,
    last: (accum, curr) => curr,
  };
  const reducer = reducers[name];
  const fn = (accum, curr) => {
    const value = reducer(accum, curr);
    kit.trace(`fn(${accum}, ${curr}) returns ${value}`);
    return value;
  };
  // The problem asks for a solution without the built-in reduce, so it is switched off during the call.
  const builtIn = Array.prototype.reduce;
  Array.prototype.reduce = function () { throw new Error('Solve it without the built-in Array.prototype.reduce.'); };
  let result;
  try {
    result = solve(nums, fn, init);
  } finally {
    Array.prototype.reduce = builtIn;
  }
  if (typeof result !== 'number') throw new Error('reduce must return a number.');
  return result;
}

