function reduce(nums, fn, init) {
  // Folding the first length elements is fn applied to the fold of the first length - 1 and the last of them.
  const foldPrefix = (length) => length === 0 ? init : fn(foldPrefix(length - 1), nums[length - 1]);
  return foldPrefix(nums.length);
}

