function generate(rand, size) {
  const names = ['sum', 'sumOfSquares', 'zero', 'max', 'hash', 'last'];
  const fn = names[Math.floor(rand() * names.length)];
  const length = size === 'small' ? Math.floor(rand() * 7) : 1000;
  const top = size === 'small' && rand() < 0.5 ? 10 : 1000;
  const nums = Array.from({ length }, () => Math.floor(rand() * (top + 1)));
  const init = rand() < 0.2 ? 0 : Math.floor(rand() * 1001);
  return [nums, fn, init];
}
